{"path": "sols/mult_nim.py", "content": "import sys


def solve(data):
    it = iter(data.split())
    n = int(next(it))
    k = int(next(it))
    steps = sorted({int(next(it)) for _ in range(k)})

    # win[pos] = True 表示轮到当前玩家时还剩 pos 颗且存在必胜策略
    # win[0] = False (轮到你时无石可取 => 对手取了最后一颗 => 你败)
    win = [False] * (n + 1)
    for pos in range(1, n + 1):
        for s in steps:
            if s > pos:
                break  # steps 已升序, 后续更大
            if not win[pos - s]:   # 走到一个让对手必败的局面
                win[pos] = True
                break

    if not win[n]:
        return "LOSE"
    # 数值最小的必胜首取数
    for s in steps:
        if s <= n and not win[n - s]:
            return "WIN %d" % s
    return "LOSE"


def main():
    data = sys.stdin.read()
    sys.stdout.write(solve(data) + "\n")


def selftest():
    cases = [
        ("31 3\n1 6 10\n", "WIN 6"),
        ("19 1\n1\n", "WIN 1"),
        ("1 1\n1\n", "WIN 1"),
        ("2 1\n1\n", "LOSE"),           # 只能取 1, 2 颗 -> 必败
        ("4 2\n1 3\n", "WIN 1"),        # 取 1 后剩 3, 对手可取 3 胜 -> 取 1 不行? 检验
        ("5 2\n1 4\n", "WIN 1"),
    ]
    ok = True
    for inp, expect in cases:
        got = solve(inp)
        flag = "PASS" if got == expect else "FAIL"
        if got != expect:
            ok = False
        print("[%s] in=%r got=%r expect=%r" % (flag, inp, got, expect))
    print("SELFTEST", "PASS" if ok else "FAIL")
    return 0 if ok else 1


if __name__ == "__main__":
    if len(sys.argv) > 1 and sys.argv[1] == "--selftest":
        sys.exit(selftest())
    main()
